css:
.print-format {
    page-size: A5;
    orientation: Landscape;
    margin-top: 8.0mm;
    margin-bottom: 6.0mm;
    margin-left: 9.5mm;
    margin-right: 9.5mm;
    padding: 0 !important;
}

@media print {
    html, body {
        margin: 0 !important;
        padding: 0 !important;
        background: #fff !important;
        -webkit-print-color-adjust: exact;
        print-color-adjust: exact;
        width: 100% !important;
        font-family: Arial, 'Helvetica Neue', Helvetica, 'Mukta Malar', 'Latha', sans-serif !important;
        font-size: 8px !important;
        line-height: 1.15 !important;
        color: #000 !important;
    }
    @page {
        size: A5 landscape;
        margin: 8.0mm 9.5mm 6.0mm 9.5mm;
    }
    .print-format {
        padding: 0 !important;
        margin: 0 !important;
    }
    .form-25b-container {
        width: 100% !important;
        max-width: 100% !important;
        border: none !important;
        box-sizing: border-box !important;
        page-break-inside: avoid !important;
        break-inside: avoid !important;
    }
}

* {
    box-sizing: border-box;
}

.form-25b-container {
    width: 100%;
    max-width: 100%;
    margin: 0 auto;
    font-family: Arial, 'Helvetica Neue', Helvetica, 'Mukta Malar', 'Latha', sans-serif !important;
    font-size: 8px;
    color: #000 !important;
    background: #fff !important;
    border: none !important;
    box-sizing: border-box;
}

.form-25b-table {
    width: 100% !important;
    table-layout: fixed !important;
    border-collapse: collapse !important;
    border-spacing: 0 !important;
    border: 1px solid #000 !important;
    margin: 0 !important;
    padding: 0 !important;
    background: #fff !important;
}

.form-25b-table th, .form-25b-table td {
    border: 1px solid #000 !important;
    padding: 3.0px 5px !important;
    font-family: Arial, 'Helvetica Neue', Helvetica, 'Mukta Malar', 'Latha', sans-serif !important;
    font-size: 8px !important;
    font-weight: normal !important;
    line-height: 1.15 !important;
    color: #000 !important;
    background: #fff !important;
    vertical-align: middle;
    word-wrap: break-word;
    word-break: break-word;
}

.earnings-table {
    width: 100% !important;
    table-layout: fixed !important;
    border-collapse: collapse !important;
    border-spacing: 0 !important;
    border: 1px solid #000 !important;
    margin-top: -1px !important;
    margin-bottom: 0 !important;
    padding: 0 !important;
    background: #fff !important;
}

.earnings-table th, .earnings-table td {
    border: 1px solid #000 !important;
    padding: 3.0px 5px !important;
    font-family: Arial, 'Helvetica Neue', Helvetica, 'Mukta Malar', 'Latha', sans-serif !important;
    font-size: 8px !important;
    font-weight: normal !important;
    line-height: 1.15 !important;
    color: #000 !important;
    background: #fff !important;
    vertical-align: middle;
    word-wrap: break-word;
    word-break: break-word;
}

.company-title {
    font-size: 11px !important;
    font-weight: 700 !important;
    letter-spacing: 0.5px;
    line-height: 1.2 !important;
}

.company-tamil {
    font-size: 9px !important;
    font-weight: normal !important;
    margin-top: 1px;
    line-height: 1.2 !important;
}

.factory-addr {
    font-size: 7.5px !important;
    font-weight: normal !important;
    margin-top: 1px;
    line-height: 1.15 !important;
}

.statutory-rule {
    font-size: 7.5px !important;
    font-weight: normal !important;
    line-height: 1.15 !important;
    margin-top: 1px;
}

.text-right {
    text-align: right !important;
}

.text-center {
    text-align: center !important;
}

html:
{% set emp = frappe.get_doc("Employee", doc.employee) if doc.employee else {} %}
{% set working_days = (doc.fixed_working_days or (26 if (doc.working_days_basis == 'Fixed Number of Days' or doc.total_working_days == 26) else (doc.total_working_days or 26))) | float %}
{% set lop_days = (doc.lop_days if doc.lop_days is defined and doc.lop_days is not none else (doc.unpaid_leave_days if doc.unpaid_leave_days is defined and doc.unpaid_leave_days is not none else (doc.no_of_leave or 0))) | float %}
{% set holidays = (doc.holiday_count or 0) | float %}
{% set cl_count = (doc.no_of_paid_leave or 0) | float %}
{% set paid_days = [0, working_days - lop_days] | max %}
{% if doc.physical_attendance_days is defined and doc.physical_attendance_days is not none and (doc.physical_attendance_days | float) > 0 and (doc.physical_attendance_days | float) <= paid_days %}
    {% set days_worked = doc.physical_attendance_days | float %}
{% else %}
    {% set days_worked = [0, paid_days - holidays - cl_count] | max %}
{% endif %}

<div class="form-25b-container">
    <!-- Table 1: Header & Employee Demographic Information (6 Columns) -->
    <table class="form-25b-table">
        <!-- Factory & Company Header Row 1 -->
        <tr>
            <td colspan="4" class="text-center" style="padding: 3.0px 5px !important; vertical-align: middle;">
                <div class="company-title">BBK EXPORTS PRIVATE LIMITED</div>
                <div class="company-tamil">பிபிகே எக்ஸ்போர்ட்ஸ் பிரைவேட் லிமிடெட்</div>
                <div class="factory-addr">21, கீழம்பி கிராமம், கிருஷ்ணாபுரம் போஸ்ட், காஞ்சிபுரம் - 631 551 - KPM-10227</div>
            </td>
            <td colspan="2" class="text-center" style="padding: 3.0px 5px !important; vertical-align: middle;">
                <div style="font-weight: 700 !important; font-size: 9px !important;">Pay Slip / Form 25B</div>
                <div class="statutory-rule">
                    (Under rule 27(2) of the Minimum wages (Chennai) rule 1953 under rule 103 (B))
                </div>
            </td>
        </tr>

        <!-- Header Row 2: Pay Slip Month -->
        <tr>
            <td colspan="6" class="text-center" style="font-weight: 700 !important; font-size: 9px !important; padding: 3.0px !important;">
                Pay Slip For The Month / சம்பளப்பட்டியல் மாதம் - {{ frappe.utils.formatdate(doc.pay_period_start, "MMM yyyy") }}
            </td>
        </tr>

        <!-- Employee Demographic Details Grid (6 Fixed Columns Totaling 100%) -->
        <tr>
            <td style="width: 20%;">Employee Name / தொழிலாளியின் பெயர்</td>
            <td style="width: 16%;">{{ doc.employee_name or "-" }}</td>
            <td style="width: 20%;">Father/Husband Name / தகப்பனார்/கணவர் பெயர்</td>
            <td style="width: 18%;">{{ doc.father_husband_name or (emp.father_husband_name if emp else "-") or "-" }}</td>
            <td style="width: 13%;">DOB / பிறந்த தேதி</td>
            <td style="width: 13%;">{{ frappe.utils.formatdate(emp.dob, "dd/MM/yyyy") if emp and emp.dob else "-" }}</td>
        </tr>
        <tr>
            <td>Employee No / தொழிலாளியின் எண்</td>
            <td>{{ emp.employee_id or doc.employee }}</td>
            <td>Department / துறை</td>
            <td>{{ doc.department or "-" }}</td>
            <td>DOJ / பணி சேர்ந்த தேதி</td>
            <td>{{ frappe.utils.formatdate(doc.date_of_joining, "dd/MM/yyyy") if doc.date_of_joining else "-" }}</td>
        </tr>
        <tr>
            <td>Working Days / பணி நாட்கள்</td>
            <td>{{ "{:.0f}".format(working_days | float) }}</td>
            <td>Account No / வங்கி எண்</td>
            <td style="font-size: 8px;">{{ doc.account_no or emp.bank_account or "-" }}</td>
            <td>PF No. / பி.எஃப் எண்</td>
            <td style="font-size: 8px;">{{ doc.pf_no or emp.pf_number or "-" }}</td>
        </tr>
        <tr>
            <td>Days Worked / வருகை நாள்</td>
            <td>{{ "{:.0f}".format(days_worked | float) }}</td>
            <td>LOP Days / இழப்பீட்டு நாள்</td>
            <td>{{ "{:.0f}".format(lop_days | float) }}</td>
            <td>ESI No. / இ.எஸ்.ஐ எண்</td>
            <td style="font-size: 8px;">{{ doc.esi_no or emp.esi_no or "-" }}</td>
        </tr>
        <tr>
            <td>Holidays / விடுமுறை</td>
            <td>{{ "{:.0f}".format(holidays | float) }}</td>
            <td>Salary Paid Days / சம்பளம் வழங்கப்படும் நாள்</td>
            <td>{{ "{:.0f}".format(paid_days | float) }}</td>
            <td style="font-weight: 700;">CL Balance / விடுப்பு இருப்பு</td>
            <td style="font-weight: 700;">{{ "{:.0f}".format(doc.cl_balance | float) if doc.cl_balance is defined and doc.cl_balance is not none else "0" }}</td>
        </tr>
    </table>

    <!-- Table 2: Dynamic Earnings & Deductions Grid (5 Columns) -->
    <table class="earnings-table">
        <tr>
            <th colspan="3" class="text-center" style="width: 50%; font-weight: normal !important;">EARNINGS / ஈட்டுதல்</th>
            <th colspan="2" class="text-center" style="width: 50%; font-weight: normal !important;">DEDUCTIONS / பிடித்தங்கள்</th>
        </tr>
        <tr style="font-size: 8px;">
            <th style="width: 26%; font-weight: normal !important;">PARTICULARS / விவரங்கள்</th>
            <th class="text-right" style="width: 12%; font-weight: normal !important;">RATE OF WAGES (Rs.) / நிர்ணயிக்கப்பட்ட சம்பளம்</th>
            <th class="text-right" style="width: 12%; font-weight: normal !important;">ACTUAL EARNINGS (Rs.) / ஈட்டிய சம்பளம்</th>
            <th style="width: 32%; font-weight: normal !important;">DEDUCTIONS (Rs.) / பிடித்தங்கள்</th>
            <th class="text-right" style="width: 18%; font-weight: normal !important;">AMOUNT (Rs.) / தொகை</th>
        </tr>

        <!-- Dynamic Lists Construction & Extraction -->
        {% set clean_earnings = [] %}
        {% set total_rate = namespace(val=0) %}
        {% set total_actual = namespace(val=0) %}

        {% for row in doc.earnings %}
            {% set cname = (row.component_name or row.salary_component or "") %}
            {% set amt = (row.amount or 0) | float %}
            {% set std_amt = (row.standard_amount if (row.standard_amount is defined and row.standard_amount is not none and (row.standard_amount | float) > 0) else amt) | float %}
            {% set cname_lower = cname | lower %}
            {% set is_dynamic = ("overtime" in cname_lower or cname_lower == "ot" or "ot pay" in cname_lower or "attendance" in cname_lower or "bonus" in cname_lower or "pib" in cname_lower) and (row.standard_amount is not defined or not row.standard_amount or (row.standard_amount | float) == 0) %}

            {% if not is_dynamic %}
                {% set total_rate.val = total_rate.val + std_amt %}
                {% set rate_display = "{:,.0f}".format(std_amt) %}
            {% else %}
                {% set rate_display = "-" %}
            {% endif %}
            {% set total_actual.val = total_actual.val + amt %}

            <!-- Bilingual Tamil label mapping -->
            {% set tamil_lbl = "" %}
            {% if "basic" in cname_lower %}
                {% set tamil_lbl = "அடிப்படை ஊதியம்" %}
            {% elif "da" in cname_lower or "dearness" in cname_lower %}
                {% set tamil_lbl = "பஞ்சப்படி" %}
            {% elif "hra" in cname_lower or "house" in cname_lower %}
                {% set tamil_lbl = "வீட்டு வாடகைப்படி" %}
            {% elif "other allowance" in cname_lower or cname_lower == "oa" %}
                {% set tamil_lbl = "இதர படி" %}
            {% elif "overtime" in cname_lower or cname_lower == "ot" or "ot pay" in cname_lower %}
                {% set tamil_lbl = "மிகை நேர சம்பளம்" %}
            {% elif "attendance" in cname_lower %}
                {% set tamil_lbl = "வருகை போனஸ்" %}
            {% elif "pib" in cname_lower or "incentive" in cname_lower %}
                {% set tamil_lbl = "செயல்திறன் ஊக்க போனஸ்" %}
            {% elif "tea" in cname_lower %}
                {% set tamil_lbl = "தேநீர் படி" %}
            {% elif "bonus" in cname_lower %}
                {% set tamil_lbl = "போனஸ்" %}
            {% elif "el" in cname_lower or "earned leave" in cname_lower %}
                {% set tamil_lbl = "ஈட்டிய விடுப்பு சம்பளம்" %}
            {% endif %}

            {% set display_title = cname %}
            {% if ("overtime" in cname_lower or cname_lower == "ot" or "ot pay" in cname_lower) and doc.ot_hours and (doc.ot_hours | float) > 0 %}
                {% set display_title = cname ~ " (" ~ "{:.0f}".format(doc.ot_hours | float) ~ " Hrs)" %}
            {% endif %}

            {% set full_label = display_title ~ (" / " ~ tamil_lbl if tamil_lbl else "") %}
            {% set _ = clean_earnings.append({
                "label": full_label,
                "rate": rate_display,
                "actual": "{:,.0f}".format(amt)
            }) %}
        {% endfor %}

        {% set clean_deductions = [] %}
        {% set total_ded = namespace(val=0) %}

        {% for row in doc.deductions %}
            {% set dname = (row.component_name or row.salary_component or "") %}
            {% set damt = (row.amount or 0) | float %}
            {% set total_ded.val = total_ded.val + damt %}
            {% set dname_lower = dname | lower %}

            <!-- Bilingual Tamil deduction label mapping -->
            {% set tamil_dlbl = "" %}
            {% if "pf" in dname_lower or "provident" in dname_lower or "epf" in dname_lower %}
                {% set tamil_dlbl = "பி.எஃப்" %}
            {% elif "esi" in dname_lower or "insurance" in dname_lower %}
                {% set tamil_dlbl = "இ.எஸ்.ஐ" %}
            {% elif "prof" in dname_lower or "pt" in dname_lower or "tax" in dname_lower %}
                {% set tamil_dlbl = "தொழில்வரி" %}
            {% elif "canteen" in dname_lower or "food" in dname_lower or "mess" in dname_lower or "lunch" in dname_lower %}
                {% set tamil_dlbl = "உணவகம்" %}
            {% elif "uniform" in dname_lower %}
                {% set tamil_dlbl = "சீருடை" %}
            {% elif "advance" in dname_lower or "loan" in dname_lower %}
                {% set tamil_dlbl = "சம்பள முன்பணம்" %}
            {% elif "lwf" in dname_lower or "welfare" in dname_lower %}
                {% set tamil_dlbl = "தொழிலாளர் நல நிதி" %}
            {% elif "tds" in dname_lower %}
                {% set tamil_dlbl = "வருமான வரி" %}
            {% endif %}

            {% set full_dlabel = dname ~ (" / " ~ tamil_dlbl if tamil_dlbl else "") %}
            {% set _ = clean_deductions.append({
                "label": full_dlabel,
                "amount": "{:,.0f}".format(damt)
            }) %}
        {% endfor %}

        <!-- Fallbacks if lists are empty -->
        {% if clean_earnings | length == 0 %}
            {% set _ = clean_earnings.append({"label": "Gross Salary / மொத்த சம்பளம்", "rate": "{:,.0f}".format(doc.gross_pay or 0), "actual": "{:,.0f}".format(doc.gross_pay or 0)}) %}
            {% set total_rate.val = doc.gross_pay or 0 %}
            {% set total_actual.val = doc.gross_pay or 0 %}
        {% endif %}

        {% set max_rows = [clean_earnings | length, clean_deductions | length] | max %}
        {% set final_total_rate = total_rate.val if total_rate.val > 0 else (doc.gross_pay or 0) %}
        {% set final_total_actual = doc.grand_gross_pay or doc.gross_pay or total_actual.val %}
        {% set final_total_ded = doc.total_deduction or total_ded.val %}
        {% set final_net_paid = doc.grand_net_pay or doc.net_pay or (final_total_actual - final_total_ded) %}

        <!-- Dynamic Render Rows Loop -->
        {% for i in range(max_rows) %}
            <tr>
                {% if i < clean_earnings | length %}
                    {% set e_item = clean_earnings[i] %}
                    <td>{{ e_item.label }}</td>
                    <td class="text-right">{{ e_item.rate }}</td>
                    <td class="text-right">{{ e_item.actual }}</td>
                {% elif i == clean_earnings | length %}
                    <td rowspan="{{ max_rows - clean_earnings | length }}"></td>
                    <td class="text-right" rowspan="{{ max_rows - clean_earnings | length }}"></td>
                    <td class="text-right" rowspan="{{ max_rows - clean_earnings | length }}"></td>
                {% endif %}

                {% if i < clean_deductions | length %}
                    {% set d_item = clean_deductions[i] %}
                    <td>{{ d_item.label }}</td>
                    <td class="text-right">{{ d_item.amount }}</td>
                {% elif i == clean_deductions | length %}
                    <td rowspan="{{ max_rows - clean_deductions | length }}"></td>
                    <td class="text-right" rowspan="{{ max_rows - clean_deductions | length }}"></td>
                {% endif %}
            </tr>
        {% endfor %}

        <!-- Totals Row -->
        <tr>
            <td style="font-weight: 700 !important;">TOTAL (Rs.) / <br>மொத்தம்</td>
            <td class="text-right" style="font-weight: 700 !important;">{{ "{:,.0f}".format(final_total_rate) }}</td>
            <td class="text-right" style="font-weight: 700 !important;">{{ "{:,.0f}".format(final_total_actual) }}</td>
            <td style="font-weight: 700 !important;">TOTAL DEDUCTIONS (Rs.) / <br>மொத்த பிடித்தங்கள்</td>
            <td class="text-right" style="font-weight: 700 !important;">{{ "{:,.0f}".format(final_total_ded) }}</td>
        </tr>

        <!-- Net Paid Row -->
        <tr>
            <td colspan="3" style="font-size: 9px !important; font-weight: 700 !important; padding: 3.0px 5px !important;">
                NET PAID (Rs.) / நிகர ஊதியம்
            </td>
            <td colspan="2" class="text-right" style="font-size: 8px !important; font-weight: 700 !important; padding: 3.0px 5px !important;">
                Rs. {{ "{:,.0f}".format(final_net_paid) }}
            </td>
        </tr>

        <!-- Amount in Words -->
        <tr>
            <td colspan="5" style="padding: 3.0px 5px !important;">
                Amount in Words: {{ frappe.utils.money_in_words(final_net_paid) }}
            </td>
        </tr>

        <!-- Footer: Dates & Signature -->
        <tr>
            <td colspan="3" style="vertical-align: top; padding: 3.0px 5px !important;">
                <div>Salary Slip Issue Date : {{ frappe.utils.formatdate(doc.creation, "dd/MM/yyyy") if doc.creation else frappe.utils.formatdate(frappe.utils.nowdate(), "dd/MM/yyyy") }}</div>
                <div style="margin-top: 2px;">Salary Issue Date : {{ frappe.utils.formatdate(doc.modified, "dd/MM/yyyy") if doc.modified else frappe.utils.formatdate(frappe.utils.nowdate(), "dd/MM/yyyy") }}</div>
                <div style="font-size: 8px !important; color: #000; margin-top: 2px; font-style: italic;">
                    * This is Computer Generated Salary Slip No Signature Required
                </div>
            </td>
            <td colspan="2" style="vertical-align: bottom; text-align: center; height: 22px; padding: 3.0px 5px !important;">
                <div style="border-top: 1px dashed #000; width: 85%; margin: 5px auto 0 auto; padding-top: 4px; font-weight: normal !important; font-size: 8px !important;">
                    Employee Signature / தொழிலாளி கையொப்பம்
                </div>
            </td>
        </tr>
    </table>
</div>
